// Gather all items from the three audit branches
const items = $input.all();

// The webhook trigger data is passed through via the initial node
const webhookData = $('Webhook Trigger').first().json;

// Pull results from each branch
const uxResult = $('Run UX Audit').first().json;
const seoResult = $('Run SEO Audit').first().json;
const appResult = $('Run App Audit').first().json;

return [{
  json: {
    // Prospect info from webhook
    company_name: webhookData.company_name,
    website_url: webhookData.website_url,
    contact_name: webhookData.contact_name,
    contact_email: webhookData.contact_email,
    industry: webhookData.industry || '',

    // UX audit
    ux_score: uxResult.overall_score,
    ux_grade: uxResult.grade,
    ux_summary: uxResult.summary,
    ux_hook: uxResult.email_hook,
    ux_top_issues: uxResult.top_issues || [],

    // SEO audit
    seo_score: seoResult.overall_score,
    seo_grade: seoResult.grade,
    seo_summary: seoResult.summary,
    seo_hook: seoResult.email_hook,
    seo_top_issues: seoResult.top_issues || [],

    // App audit
    app_has_ios: appResult.has_ios_app,
    app_has_android: appResult.has_android_app,
    app_ios_rating: appResult.ios_rating,
    app_opportunity_score: appResult.opportunity_score,
    app_opportunity_grade: appResult.opportunity_grade,
    app_recommendation: appResult.recommendation,
    app_recommendation_label: appResult.recommendation_label,
    app_summary: appResult.summary,
    app_hook: appResult.email_hook,
    app_rationale: appResult.rationale,
    competitors_have_apps: appResult.competitors_have_apps
  }
}];

