parameters.jsCode:
const emailResponse = $('Generate Email Copy').first().json;
const data = $('Merge Audit Results').first().json;
const htmlResponse = $('Generate HTML Concept').first().json;

// Parse email JSON
const textBlock = emailResponse.content?.find(b => b.type === 'text');
let emailData = { subject: '', body: '' };
try {
  const clean = textBlock?.text.replace(/```json|```/g, '').trim();
  emailData = JSON.parse(clean);
} catch(e) {
  emailData.subject = 'We audited ' + data.company_name + ' — 3 things to fix first';
  emailData.body = textBlock?.text || '';
}

// Extract HTML concept
const htmlBlock = htmlResponse.content?.find(b => b.type === 'text');
const htmlConcept = htmlBlock?.text || '';

// Build audit scorecard footer
const appLine = data.app_has_ios || data.app_has_android
  ? 'App: ' + (data.app_ios_rating ? data.app_ios_rating + '/5 rating' : 'exists') + ' | Opportunity: ' + data.app_opportunity_grade
  : 'App: No app detected | Opportunity: ' + data.app_opportunity_grade + ' (' + data.app_recommendation_label + ')';

const scorecard = [
  '',
  '--- RUONALIM AUDIT REPORT ---',
  'Site: ' + data.website_url,
  'UX Score: ' + data.ux_score + '/100 (' + data.ux_grade + ') | ' + data.ux_summary,
  'SEO Score: ' + data.seo_score + '/100 (' + data.seo_grade + ') | ' + data.seo_summary,
  appLine,
  '[CONCEPT_LINK - paste hosted HTML URL here]',
  '---'
].join('\n');

const fullBody = emailData.body + scorecard;

return [{
  json: {
    ...data,
    email_subject: emailData.subject,
    email_body: fullBody,
    html_concept: htmlConcept
  }
}];
